// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/attempts", wrapper.RecordAttempt)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/attempts/{id}", wrapper.RateAttempt)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/email/code", wrapper.SendEmailChangeCode)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/email/confirm", wrapper.ConfirmEmailChange)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/password", wrapper.PasswordLogin)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/password/change", wrapper.ChangePassword)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/recovery/code", wrapper.SendRecoveryCode)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/recovery/complete", wrapper.CompleteRecovery)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/refresh", wrapper.RefreshToken)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/register", wrapper.Register)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/register/code", wrapper.SendRegisterCode)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/auth/sessions", wrapper.ListSessions)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/sessions/revoke-others", wrapper.RevokeOtherSessions)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/sso", wrapper.SsoExchange)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/banks", wrapper.ListBanks)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/banks/{slug}", wrapper.GetBank)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/banks/{slug}/questions", wrapper.ListQuestions)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/banks/{slug}/questions/summary", wrapper.SummarizeQuestions)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/banks/{slug}/tags", wrapper.ListBankTags)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me/bank", wrapper.GetMyBank)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/me/bank", wrapper.ChooseMyBank)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/me/bookmarks/{questionId}", wrapper.RemoveBookmark)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/me/bookmarks/{questionId}", wrapper.AddBookmark)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me/overview", wrapper.GetMyOverview)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me/progress", wrapper.GetMyProgress)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me/recent", wrapper.GetMyRecent)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me/resume", wrapper.GetMyResume)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me/tag-stats", wrapper.GetMyTagStats)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/questions/{id}", wrapper.GetQuestion)
	})

	return r
}

