// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 记录一次作答（揭晓即记录；对错由服务端按参考答案判定）
	// (POST /attempts)
	RecordAttempt(ctx context.Context, request RecordAttemptRequestObject) (RecordAttemptResponseObject, error)
	// 给一条已记录的作答补上自评（只记录，⛔ 不再推进卡片）
	// (PATCH /attempts/{id})
	RateAttempt(ctx context.Context, request RateAttemptRequestObject) (RateAttemptResponseObject, error)
	// 给新邮箱发验证码（改邮箱第一步）
	// (POST /auth/email/code)
	SendEmailChangeCode(ctx context.Context, request SendEmailChangeCodeRequestObject) (SendEmailChangeCodeResponseObject, error)
	// 确认改邮箱
	// (POST /auth/email/confirm)
	ConfirmEmailChange(ctx context.Context, request ConfirmEmailChangeRequestObject) (ConfirmEmailChangeResponseObject, error)
	// 登出（吊销该会话）
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// 用户名密码登录
	// (POST /auth/password)
	PasswordLogin(ctx context.Context, request PasswordLoginRequestObject) (PasswordLoginResponseObject, error)
	// 修改密码 / 首次设置密码
	// (POST /auth/password/change)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// 发找回验证码
	// (POST /auth/recovery/code)
	SendRecoveryCode(ctx context.Context, request SendRecoveryCodeRequestObject) (SendRecoveryCodeResponseObject, error)
	// 用验证码重置密码
	// (POST /auth/recovery/complete)
	CompleteRecovery(ctx context.Context, request CompleteRecoveryRequestObject) (CompleteRecoveryResponseObject, error)
	// 用 refresh token 换新的 access token
	// (POST /auth/refresh)
	RefreshToken(ctx context.Context, request RefreshTokenRequestObject) (RefreshTokenResponseObject, error)
	// 完成注册
	// (POST /auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// 发注册验证码
	// (POST /auth/register/code)
	SendRegisterCode(ctx context.Context, request SendRegisterCodeRequestObject) (SendRegisterCodeResponseObject, error)
	// 我的登录设备
	// (GET /auth/sessions)
	ListSessions(ctx context.Context, request ListSessionsRequestObject) (ListSessionsResponseObject, error)
	// 登出其它设备（保留当前这台）
	// (POST /auth/sessions/revoke-others)
	RevokeOtherSessions(ctx context.Context, request RevokeOtherSessionsRequestObject) (RevokeOtherSessionsResponseObject, error)
	// 用 Akasha id_token 换取本 API 的 token
	// (POST /auth/sso)
	SsoExchange(ctx context.Context, request SsoExchangeRequestObject) (SsoExchangeResponseObject, error)
	// 题库列表
	// (GET /banks)
	ListBanks(ctx context.Context, request ListBanksRequestObject) (ListBanksResponseObject, error)
	// 题库详情与统计
	// (GET /banks/{slug})
	GetBank(ctx context.Context, request GetBankRequestObject) (GetBankResponseObject, error)
	// 题目列表（分页 + 标签筛选）
	// (GET /banks/{slug}/questions)
	ListQuestions(ctx context.Context, request ListQuestionsRequestObject) (ListQuestionsResponseObject, error)
	// 一个题目集合的本轮小结（P9
	// (GET /banks/{slug}/questions/summary)
	SummarizeQuestions(ctx context.Context, request SummarizeQuestionsRequestObject) (SummarizeQuestionsResponseObject, error)
	// 题库的标签列表（用于筛选与正确率热图）
	// (GET /banks/{slug}/tags)
	ListBankTags(ctx context.Context, request ListBankTagsRequestObject) (ListBankTagsResponseObject, error)
	// 当前题库（首页显示哪一个）
	// (GET /me/bank)
	GetMyBank(ctx context.Context, request GetMyBankRequestObject) (GetMyBankResponseObject, error)
	// 切换当前题库（设置页）
	// (PUT /me/bank)
	ChooseMyBank(ctx context.Context, request ChooseMyBankRequestObject) (ChooseMyBankResponseObject, error)
	// 取消收藏（幂等：本来没收藏也是 204）
	// (DELETE /me/bookmarks/{questionId})
	RemoveBookmark(ctx context.Context, request RemoveBookmarkRequestObject) (RemoveBookmarkResponseObject, error)
	// 收藏一题（P9
	// (PUT /me/bookmarks/{questionId})
	AddBookmark(ctx context.Context, request AddBookmarkRequestObject) (AddBookmarkResponseObject, error)
	// 跨题库总览（今天 / 连续天数 / 累计）
	// (GET /me/overview)
	GetMyOverview(ctx context.Context, request GetMyOverviewRequestObject) (GetMyOverviewResponseObject, error)
	// 我的学习进度总览
	// (GET /me/progress)
	GetMyProgress(ctx context.Context, request GetMyProgressRequestObject) (GetMyProgressResponseObject, error)
	// 最近的学习会话（跨题库）
	// (GET /me/recent)
	GetMyRecent(ctx context.Context, request GetMyRecentRequestObject) (GetMyRecentResponseObject, error)
	// 继续学习（上次刷到哪）
	// (GET /me/resume)
	GetMyResume(ctx context.Context, request GetMyResumeRequestObject) (GetMyResumeResponseObject, error)
	// 按标签的正确率（「我哪里不会」）
	// (GET /me/tag-stats)
	GetMyTagStats(ctx context.Context, request GetMyTagStatsRequestObject) (GetMyTagStatsResponseObject, error)
	// 单题详情（题干 + 选项 + 各方答案主张 + 解析 + 标签）
	// (GET /questions/{id})
	GetQuestion(ctx context.Context, request GetQuestionRequestObject) (GetQuestionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// RecordAttempt operation middleware
func (sh *strictHandler) RecordAttempt(w http.ResponseWriter, r *http.Request) {
	var request RecordAttemptRequestObject

	var body RecordAttemptJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.RecordAttempt(ctx, request.(RecordAttemptRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "RecordAttempt")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(RecordAttemptResponseObject); ok {
		if err := validResponse.VisitRecordAttemptResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

